// @pit: {"label": "Commit fix and release 0.36.5 on a release branch and push"}
async ({ shell: { execFile }, delivery: { commit } }) => {
  await execFile("git", ["switch", "-c", "release-0.36.5"], { raise: true });
  const a = await commit({
    files: ["src/durable/present.ts", "test/durable/present.test.ts", "docs/durable.md"],
    message: "fix(durable): present any stored typescript call and result

From pi-action's review of the present field:
- a call with no label and blank code gets a title (functionId or
  "typescript") instead of an empty one;
- a saveOnly result without a savedFunction names the functionId or the
  declared function, or has no summary, instead of "saved undefined";
- results without Pit's details and arguments whose code is not a string
  are shown by their text instead of throwing;
- a result that asked a question is summarized as "asked: <title>".

Refs #372",
  });
  const b = await commit({
    files: ["CHANGELOG.md", "README.md", "package.json", "package-lock.json"],
    message: "chore(release): v0.36.5

- the typescript tool's present field handles every stored call and result

Refs #372",
    push: true,
  });
  return [a.sha, b.sha, b.upstream];
}
